package cn.nebulaedata.cccs.nebuwork.backend.api.platformmcp;

import cn.nebulaedata.cccs.nebuwork.backend.api.agent.*;
import cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException;
import cn.nebulaedata.cccs.nebuwork.backend.api.knowledge.KnowledgeService;
import cn.nebulaedata.cccs.nebuwork.backend.api.workbench.WorkbenchMapper;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.security.SecureRandom;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.BusinessValues.*;

/** Business identity, immutable/current policy intersection and durable operation boundary. */
@Service
public class PlatformMcpService {
    final AgentStore db;final AgentTasks tasks;final AgentClient engine;final WorkbenchMapper workbenches;
    final ObjectMapper json;final PlatformMcpCatalog catalog;final PlatformMcpDispatch dispatch;
    final KnowledgeService knowledge;final TransactionTemplate tx;
    final String endpoint,serviceKey;
    public PlatformMcpService(AgentStore db,AgentTasks tasks,AgentClient engine,WorkbenchMapper workbenches,ObjectMapper json,PlatformMcpCatalog catalog,PlatformMcpDispatch dispatch,KnowledgeService knowledge,PlatformTransactionManager manager,
        @Value("${nebu.platform-mcp.url:}")String endpoint,@Value("${nebu.platform-mcp.service-key:}")String serviceKey){this.db=db;this.tasks=tasks;this.engine=engine;this.workbenches=workbenches;this.json=json;this.catalog=catalog;this.dispatch=dispatch;this.knowledge=knowledge;tx=new TransactionTemplate(manager);this.endpoint=endpoint;this.serviceKey=serviceKey;}
    public Object catalog(){List<Object> out=new ArrayList<>();for(PlatformMcpCatalog.Tool t:catalog.all())out.add(t.dto());return map("version",PlatformMcpCatalog.VERSION,"tools",out);}
    void ownedWorkbench(String owner,String id){if(workbenches.workbench(owner,id)==null)throw new ApiException(404,"工作台不存在");}
    static ObjectNode empty(ObjectMapper json){return json.valueToTree(map("enabled",false,"scope","current_project","tools",Collections.emptyList(),"resources",Collections.emptyList()));}
    public Object policy(String owner,String id){ownedWorkbench(owner,id);Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_policy WHERE owner_id=? AND workbench_id=?",owner,id);return row==null?map("revision",0,"draft",empty(json),"published",null,"revoked",false):map("revision",row.get("revision"),"draft",decode(json,row.get("draft_json")),"published",row.get("published_json")==null?null:decode(json,row.get("published_json")),"publishedRevision",row.get("published_revision"),"revoked",row.get("revoked"));}
    public Object policyWrite(String owner,String id,String action,JsonNode body){ownedWorkbench(owner,id);return tx.execute(s->{db.one("SELECT id FROM nw_workbench WHERE id=? AND owner_id=? FOR UPDATE",id,owner);Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_policy WHERE owner_id=? AND workbench_id=? FOR UPDATE",owner,id);long rev=row==null?0:((Number)row.get("revision")).longValue();if(body.path("revision").asLong(-1)!=rev)throw new ApiException(409,"系统 MCP 授权已变化，请重新加载");
        if(action.equals("save")){JsonNode draft=validatePolicy(body.path("policy"));if(row==null)db.update("INSERT INTO nw_platform_mcp_policy(owner_id,workbench_id,revision,draft_json) VALUES(?,?,1,?)",owner,id,draft.toString());else db.update("UPDATE nw_platform_mcp_policy SET revision=revision+1,draft_json=?,updated_at=CURRENT_TIMESTAMP WHERE owner_id=? AND workbench_id=?",draft.toString(),owner,id);}
        else if(action.equals("publish")){if(row==null)throw new ApiException(409,"请先保存授权草稿");JsonNode draft=validatePolicy(decode(json,row.get("draft_json")));if(draft.path("enabled").asBoolean()&&(endpoint.isEmpty()||serviceKey.length()<32))throw new ApiException(409,"系统 MCP 服务尚未配置");db.update("UPDATE nw_platform_mcp_policy SET published_json=?,published_revision=revision,revoked=FALSE WHERE owner_id=? AND workbench_id=?",draft.toString(),owner,id);}
        else if(action.equals("revoke")){if(row!=null)db.update("UPDATE nw_platform_mcp_policy SET revoked=TRUE,revoked_before_revision=revision,revision=revision+1 WHERE owner_id=? AND workbench_id=?",owner,id);}
        else throw new ApiException(422,"不支持的授权操作");return policy(owner,id);});}
    JsonNode validatePolicy(JsonNode p){if(!p.isObject())throw new ApiException(422,"授权配置必须为对象");Set<String> fields=new HashSet<>(Arrays.asList("enabled","scope","tools","resources"));p.fieldNames().forEachRemaining(k->{if(!fields.contains(k))throw new ApiException(422,"不支持的授权字段："+k);});if(!p.path("enabled").isBoolean()||!Arrays.asList("current_project","selected","account").contains(p.path("scope").asText())||!p.path("tools").isArray()||!p.path("resources").isArray())throw new ApiException(422,"授权配置无效");Set<String> names=new HashSet<>();for(JsonNode n:p.path("tools")){catalog.get(n.asText());if(!names.add(n.asText()))throw new ApiException(422,"工具不能重复");}if(p.path("resources").size()>100)throw new ApiException(422,"最多指定100个资源");for(JsonNode r:p.path("resources")){if(!Arrays.asList("project","workbench","expert","workflow","knowledge").contains(r.path("kind").asText())||!r.path("id").isTextual()||r.path("id").asText().isEmpty()||r.path("kind").asText().equals("knowledge")&&!r.path("connectionId").isTextual())throw new ApiException(422,"指定资源无效");}return p.deepCopy();}
    public JsonNode snapshot(String owner,String project){Map<String,Object> p=tasks.project(owner,project,false);Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_policy WHERE owner_id=? AND workbench_id=?",owner,p.get("workbench_id"));if(row==null||Boolean.TRUE.equals(row.get("revoked"))||row.get("published_json")==null)return null;JsonNode policy=decode(json,row.get("published_json"));if(!policy.path("enabled").asBoolean())return null;return json.valueToTree(map("catalogVersion",PlatformMcpCatalog.VERSION,"workbenchId",p.get("workbench_id"),"policyRevision",row.get("published_revision"),"policy",policy));}
    JsonNode verifiedRun(JsonNode identity){String owner=text(identity,"ownerId",128,true),project=text(identity,"projectId",128,true);tasks.project(owner,project,true);JsonNode run=engine.get(owner,project,"/v1/runs/"+AgentClient.segment(text(identity,"runId",128,true)));if(run==null||!owner.equals(run.path("ownerId").asText())||!project.equals(run.path("projectId").asText())||!identity.path("sessionId").equals(run.path("sessionId"))||!identity.path("tenantId").equals(run.path("tenantId"))||!identity.path("manifestHash").equals(run.path("manifestHash"))||TERMINAL.contains(run.path("status").asText()))throw new ApiException(403,"系统 MCP 运行身份已失效");return run;}
    public Object grant(JsonNode identity){JsonNode run=verifiedRun(identity);Context c=context(run);String token=randomToken();long expires=System.currentTimeMillis()+600000;db.update("INSERT INTO nw_platform_mcp_grant(token_hash,owner_id,run_id,identity_json,expires_at) VALUES(?,?,?,?,?)",hash(token),c.owner,c.runId,identity.toString(),expires);return map("token",token,"expiresAt",expires,"url",endpoint,"catalogVersion",PlatformMcpCatalog.VERSION);}
    public boolean allowed(JsonNode identity,String tool){try{return context(verifiedRun(identity)).hasTool(tool);}catch(ApiException e){return false;}}
    public Object authorizeAgent(JsonNode identity){Context c=context(verifiedRun(identity));String name=identity.path("name").asText();c.requireTool(name);catalog.validate(catalog.get(name),identity.path("arguments"));dispatch.authorize(c,name,identity.path("arguments"));String call=identity.path("callId").asText();if(!call.isEmpty()){Map<String,Object> prior=db.one("SELECT * FROM nw_platform_mcp_call WHERE owner_id=? AND run_id=? AND call_id=?",c.owner,c.runId,call);if(prior!=null&&prior.get("result_json")!=null)authorizePrior(c,prior);}return map("allowed",true);}
    void authorizePrior(Context c,Map<String,Object> row){if(!fingerprint(c.current).equals(row.get("policy_hash")))throw new ApiException(403,"授权版本已变化，旧调用结果不可重用；请重新读取");if(row.get("result_json")!=null)dispatch.evidence.authorizeResult(c.owner,c.taskId,decode(json,row.get("result_json")));}
    public Object reconcileAgent(JsonNode identity){return reconcileCall(context(verifiedRun(identity)),identity.path("callId").asText(),identity.path("name").asText());}
    public Context authenticate(String token){if(token==null||token.length()<40||token.length()>100)throw new ApiException(401,"需要运行授权");Map<String,Object> g=db.one("SELECT * FROM nw_platform_mcp_grant WHERE token_hash=?",hash(token));if(g==null||Boolean.TRUE.equals(g.get("revoked"))||((Number)g.get("expires_at")).longValue()<System.currentTimeMillis())throw new ApiException(401,"运行授权已过期");return context(verifiedRun(decode(json,g.get("identity_json"))));}
    Context context(JsonNode run){JsonNode frozen=run.path("manifest").path("platformMcp");if(!PlatformMcpCatalog.VERSION.equals(frozen.path("catalogVersion").asText()))throw new ApiException(409,"本轮系统工具目录不可用，请开始新一轮");String owner=run.path("ownerId").asText(),wb=frozen.path("workbenchId").asText();Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_policy WHERE owner_id=? AND workbench_id=?",owner,wb);if(row==null||Boolean.TRUE.equals(row.get("revoked"))||row.get("published_json")==null)throw new ApiException(403,"系统 MCP 授权已撤销");if(row.get("revoked_before_revision") instanceof Number&&frozen.path("policyRevision").asLong()<=((Number)row.get("revoked_before_revision")).longValue())throw new ApiException(403,"本轮授权已被撤销，请开始新一轮");JsonNode current=decode(json,row.get("published_json"));if(!current.path("enabled").asBoolean())throw new ApiException(403,"系统 MCP 已停用");Map<String,Object> task=db.session(run.path("sessionId").asText());if(task==null&&run.hasNonNull("parentRunId")){JsonNode parent=engine.get(owner,run.path("projectId").asText(),"/v1/runs/"+AgentClient.segment(run.path("parentRunId").asText()));task=db.session(parent.path("sessionId").asText());}if(task==null||!owner.equals(task.get("owner_id")))throw new ApiException(403,"本轮缺少业务任务归属");return new Context(run,task,frozen.path("policy"),current);}
    public Object connection(Context c){List<Object> list=new ArrayList<>();for(PlatformMcpCatalog.Tool t:catalog.all())if(c.hasTool(t.name))list.add(t.dto());return map("catalogVersion",PlatformMcpCatalog.VERSION,"tools",list);}
    public Object execute(Context c,String name,JsonNode args,String callId){PlatformMcpCatalog.Tool tool=catalog.get(name);catalog.validate(tool,args);c.requireTool(name);if(callId==null||callId.isEmpty()||callId.length()>255)throw new ApiException(422,"缺少引擎工具调用编号");dispatch.authorize(c,name,args);c.sourceName=name;c.sourceArguments=args;String id="pmc-"+hash(c.owner+":"+c.runId+":"+callId).substring(0,40),digest=fingerprint(json.valueToTree(map("name",name,"args",args)));
        if(!tool.write)return recordRead(c,tool,args,callId,id,digest);
        if(!tool.remote)return tx.execute(s->invoke(c,tool,args,callId,id,digest,true));
        Map<String,Object> previous=tx.execute(s->claim(c,tool,args,callId,id,digest));if(previous!=null){authorizePrior(c,previous);return previousResult(previous);}
        try{Object result=wrap(c,dispatch.invoke(c,name,args,id),id);db.update("UPDATE nw_platform_mcp_call SET state='completed',result_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",encode(json,result),id);return result;}catch(RuntimeException e){db.update("UPDATE nw_platform_mcp_call SET state='unknown',error_message=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",safeError(e),id);throw e;}
    }
    Object recordRead(Context c,PlatformMcpCatalog.Tool t,JsonNode a,String call,String id,String digest){return tx.execute(s->{Map<String,Object> prior=claim(c,t,a,call,id,digest);if(prior!=null){authorizePrior(c,prior);return previousResult(prior);}Object result=wrap(c,dispatch.invoke(c,t.name,a,id),id);db.update("UPDATE nw_platform_mcp_call SET state='completed',result_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",encode(json,result),id);return result;});}
    Object invoke(Context c,PlatformMcpCatalog.Tool t,JsonNode a,String call,String id,String digest,boolean local){Map<String,Object> previous=claim(c,t,a,call,id,digest);if(previous!=null){authorizePrior(c,previous);return previousResult(previous);}Object result=wrap(c,dispatch.invoke(c,t.name,a,id),id);db.update("UPDATE nw_platform_mcp_call SET state='completed',result_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",encode(json,result),id);return result;}
    Map<String,Object> claim(Context c,PlatformMcpCatalog.Tool t,JsonNode a,String call,String id,String digest){Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_call WHERE id=? FOR UPDATE",id);if(row==null){try{db.update("INSERT INTO nw_platform_mcp_call(id,owner_id,run_id,task_id,call_id,tool_name,request_hash,policy_hash,arguments_json,state) VALUES(?,?,?,?,?,?,?,?,?,'started')",id,c.owner,c.runId,c.taskId,call,t.name,digest,fingerprint(c.current),a.toString());return null;}catch(org.springframework.dao.DuplicateKeyException e){row=db.one("SELECT * FROM nw_platform_mcp_call WHERE id=? FOR UPDATE",id);}}if(row==null||!digest.equals(row.get("request_hash")))throw new ApiException(409,"同一工具调用编号不能用于不同参数");return row;}
    Object previousResult(Map<String,Object> row){if(!"completed".equals(row.get("state")))throw new ApiException(409,"原调用结果待核对，操作编号："+row.get("id"));return decode(json,row.get("result_json"));}
    Object wrap(Context c,Object data,String id){JsonNode clean=scrub(json.valueToTree(data));if(clean.toString().length()>262144)clean=json.valueToTree(map("resource",resource(c,map("type","json","value",clean)),"truncated",true));return map("data",clean,"operationId",id);}
    public Object operations(String owner,int limit,int offset){return db.rows("SELECT id,run_id,task_id,tool_name,state,error_message,created_at,updated_at FROM nw_platform_mcp_call WHERE owner_id=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",owner,Math.min(100,Math.max(1,limit)),Math.max(0,offset));}
    Object operation(Context c,String id){Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_call WHERE owner_id=? AND id=?",c.owner,id);if(row==null)throw new ApiException(404,"调用记录不存在");if(!c.runId.equals(row.get("run_id")))throw new ApiException(403,"调用记录不属于本轮");c.requireTool(str(row,"tool_name"));authorizePrior(c,row);dispatch.authorize(c,str(row,"tool_name"),decode(json,row.get("arguments_json")));return map("id",id,"state",row.get("state"),"tool",row.get("tool_name"),"result",row.get("result_json")==null?null:decode(json,row.get("result_json")),"error",row.get("error_message"));}
    public Object userOperation(String owner,String id){Map<String,Object> row=db.one("SELECT id,run_id,task_id,tool_name,state,error_message,created_at,updated_at FROM nw_platform_mcp_call WHERE owner_id=? AND id=?",owner,id);if(row==null)throw new ApiException(404,"调用记录不存在");return row;}
    Object reconcile(Context c,String id){Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_call WHERE owner_id=? AND run_id=? AND id=?",c.owner,c.runId,id);if(row==null)return map("status","not_started");String name=str(row,"tool_name");c.requireTool(name);authorizePrior(c,row);JsonNode args=decode(json,row.get("arguments_json"));dispatch.authorize(c,name,args);if("completed".equals(row.get("state")))return map("status","completed","result",decode(json,row.get("result_json")));c.sourceName=name;c.sourceArguments=args;Object recovered=dispatch.recover(c,name,args,id);if(recovered!=null){Object result=wrap(c,recovered,id);db.update("UPDATE nw_platform_mcp_call SET state='completed',result_json=?,error_message=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?",encode(json,result),id);return map("status","completed","result",result);}return map("status","unknown","operationId",id,"message","仅可使用原业务操作回执恢复，不会自动重新提交");}
    public Object reconcileCall(Context c,String callId,String name){String id="pmc-"+hash(c.owner+":"+c.runId+":"+callId).substring(0,40);Map<String,Object> row=db.one("SELECT tool_name FROM nw_platform_mcp_call WHERE owner_id=? AND run_id=? AND id=?",c.owner,c.runId,id);if(row!=null&&!name.equals(row.get("tool_name")))throw new ApiException(409,"原调用工具名称不匹配");return reconcile(c,id);}
    String resource(Context c,Object descriptor){ObjectNode source=json.valueToTree(descriptor);source.put("policyHash",fingerprint(c.current));if(c.sourceName!=null){source.put("sourceTool",c.sourceName);source.set("sourceArguments",c.sourceArguments);}String id="pmr-"+randomToken();db.update("INSERT INTO nw_platform_mcp_resource(id,owner_id,run_id,descriptor_json,expires_at) VALUES(?,?,?,?,?)",id,c.owner,c.runId,source.toString(),System.currentTimeMillis()+86400000);return "nebuwork://resource/"+id;}
    JsonNode resourceDescriptor(Context c,String uri){if(!uri.startsWith("nebuwork://resource/"))throw new ApiException(422,"无效资源句柄");Map<String,Object> row=db.one("SELECT * FROM nw_platform_mcp_resource WHERE id=? AND owner_id=? AND run_id=?",uri.substring(20),c.owner,c.runId);if(row==null||((Number)row.get("expires_at")).longValue()<System.currentTimeMillis())throw new ApiException(404,"资源句柄已失效");return decode(json,row.get("descriptor_json"));}
    static String randomToken(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
    static String safeError(Exception e){return e instanceof ApiException?e.getMessage().substring(0,Math.min(900,e.getMessage().length())):"业务调用结果需要核对";}
    static JsonNode scrub(JsonNode value){JsonNode v=value.deepCopy();if(v.isObject()){Iterator<String> it=v.fieldNames();List<String> keys=new ArrayList<>();it.forEachRemaining(keys::add);for(String k:keys){String lower=k.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");if(lower.matches(".*(password|secret|cipher|apikey|accesskey|credential|authorization|signedurl|objectkey|bank_id|bankid).*" )||Arrays.asList("headers","env","endpoint","baseurl","url","downloadurl","previewurl","mediaurl","accesstoken","cost","price","pricing","currency").contains(lower))((ObjectNode)v).remove(k);else ((ObjectNode)v).set(k,scrub(v.get(k)));}}else if(v.isArray())for(int i=0;i<v.size();i++)((ArrayNode)v).set(i,scrub(v.get(i)));return v;}
    final class Context {
        PlatformMcpService getOuter(){return PlatformMcpService.this;}
        final JsonNode run,manifest,frozen,current;final String owner,projectId,runId,taskId,workbenchId;String sourceName;JsonNode sourceArguments;
        Context(JsonNode run,Map<String,Object> task,JsonNode frozen,JsonNode current){this.run=run;manifest=run.path("manifest");this.frozen=frozen;this.current=current;owner=run.path("ownerId").asText();projectId=run.path("projectId").asText();runId=run.path("id").asText();taskId=str(task,"id");workbenchId=str(tasks.project(owner,projectId,false),"workbench_id");}
        boolean accountScope(){return !run.hasNonNull("parentRunId")&&"account".equals(frozen.path("scope").asText())&&"account".equals(current.path("scope").asText());}
        boolean contains(JsonNode a,String v){if(v==null)return false;for(JsonNode n:a)if(v.equals(n.asText()))return true;return false;}
        boolean hasTool(String name){return contains(frozen.path("tools"),name)&&contains(current.path("tools"),name);}
        void requireTool(String name){if(!hasTool(name))throw new ApiException(403,"本轮未授权此系统工具");}
        boolean selected(JsonNode p,String kind,String id,String connection){for(JsonNode r:p.path("resources"))if(kind.equals(r.path("kind").asText())&&id.equals(r.path("id").asText())&&(!kind.equals("knowledge")||connection.equals(r.path("connectionId").asText())))return true;return false;}
        boolean permits(JsonNode p,String kind,String id,String connection){String scope=p.path("scope").asText();if(!run.hasNonNull("parentRunId")&&scope.equals("account"))return true;if(!run.hasNonNull("parentRunId")&&scope.equals("selected")&&selected(p,kind,id,connection))return true;if(kind.equals("project"))return projectId.equals(id);if(kind.equals("workbench"))return workbenchId.equals(id);if(kind.equals("expert")){if(run.hasNonNull("parentRunId"))return manifest.path("primaryExpertId").asText().equals(id);for(JsonNode e:manifest.path("experts"))if(id.equals(e.path("id").asText()))return true;return id.equals(manifest.path("primaryExpertId").asText());}if(kind.equals("knowledge")){for(JsonNode ref:manifest.path("knowledgeReferences")){for(Map<String,Object> currentRef:knowledge.references(owner,ref.path("scopeKind").asText(),ref.path("scopeId").asText()))if(ref.path("id").asText().equals(currentRef.get("id"))&&id.equals(currentRef.get("collectionId"))&&connection.equals(currentRef.get("connectionId")))return true;}}if(kind.equals("workflow")){for(Map<String,Object> link:db.rows("SELECT s.expert_id FROM nw_sop_workflow w JOIN nw_sop s ON s.id=w.sop_id WHERE w.owner_id=? AND w.workflow_id=?",owner,id))if(permits(p,"expert",str(link,"expert_id"),""))return true;}return false;}
        boolean allows(String kind,String id){return allows(kind,id,"");}
        boolean allows(String kind,String id,String connection){return permits(frozen,kind,id,connection)&&permits(current,kind,id,connection);}
        void require(String kind,String id){if(!allows(kind,id))throw new ApiException(403,"目标资源不属于本轮授权范围");}
        void library(String connection,String id){if(!allows("knowledge",id,connection))throw new ApiException(403,"知识库不属于本轮授权范围");}
    }
}
